CREATE TABLE listings (phone CHAR(11) PRIMARY KEY, business_name VARCHAR(150) NOT NULL, category VARCHAR(100) NOT NULL, website VARCHAR(255) NOT NULL, evidence_url VARCHAR(255) NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE limits (bucket CHAR(64) PRIMARY KEY, hits INT NOT NULL, expires_at BIGINT NOT NULL) ENGINE=InnoDB;
